# Terraform Module: S3 + RDS + IAM for Dev/Prod

Below is an idiomatic Terraform implementation supporting the canonical scenario via `.tfvars` files.

## Directory Structure

```
.
├── terraform.tf          # Backend & provider config
├── main.tf               # Root composition
├── variables.tf          # Input variables
├── outputs.tf            # Outputs
├── dev.tfvars            # Dev environment config
├── prod.tfvars           # Prod environment config
└── modules/
    ├── s3_bucket/
    │   ├── main.tf
    │   ├── variables.tf
    │   └── outputs.tf
    ├── rds_postgres/
    │   ├── main.tf
    │   ├── variables.tf
    │   └── outputs.tf
    └── iam_role/
        ├── main.tf
        ├── variables.tf
        └── outputs.tf
```

---

## terraform.tf

```hcl
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  # Backend: adapt to your state bucket (or use local for demo)
  backend "s3" {
    bucket         = "terraform-state-bucket"
    key            = "infrastructure/terraform.tfstate"
    region         = "us-east-1"
    encrypt        = true
    dynamodb_table = "terraform-locks"
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Environment = var.environment
      ManagedBy   = "Terraform"
      CreatedAt   = "2026-08-27"
    }
  }
}
```

---

## variables.tf (Root)

```hcl
variable "environment" {
  description = "Environment name (dev or prod)"
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be 'dev' or 'prod'."
  }
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Project name for resource naming"
  type        = string
}

# S3 Bucket Config
variable "s3_bucket_name" {
  description = "S3 bucket name"
  type        = string
}

variable "enable_s3_replication" {
  description = "Enable cross-region replication (prod only)"
  type        = bool
  default     = false
}

variable "s3_replication_region" {
  description = "Target region for S3 replication"
  type        = string
  default     = "us-west-2"
}

# RDS Config
variable "rds_instance_class" {
  description = "RDS instance class (db.t3.micro, db.t3.medium, etc.)"
  type        = string
}

variable "rds_allocated_storage" {
  description = "Allocated storage in GB"
  type        = number
  default     = 20
}

variable "rds_multi_az" {
  description = "Enable Multi-AZ deployment"
  type        = bool
  default     = false
}

variable "rds_db_name" {
  description = "Database name"
  type        = string
  default     = "appdb"
}

variable "rds_master_username" {
  description = "Master username for RDS"
  type        = string
  default     = "postgres"
  sensitive   = true
}

variable "rds_master_password" {
  description = "Master password for RDS (store in Secrets Manager or SOPS)"
  type        = string
  sensitive   = true
}

variable "rds_backup_retention_days" {
  description = "Backup retention in days"
  type        = number
  default     = 7
}

# IAM Config
variable "iam_role_name" {
  description = "IAM role name for service account"
  type        = string
}

variable "oidc_provider_arn" {
  description = "OIDC provider ARN (EKS) for prod IRSA"
  type        = string
  default     = ""
}

variable "oidc_aud" {
  description = "OIDC audience (typically 'sts.amazonaws.com')"
  type        = string
  default     = "sts.amazonaws.com"
}

variable "namespace" {
  description = "Kubernetes namespace for service account"
  type        = string
  default     = "default"
}

variable "service_account_name" {
  description = "Kubernetes service account name"
  type        = string
  default     = "app-sa"
}
```

---

## main.tf (Root)

```hcl
module "s3_bucket" {
  source = "./modules/s3_bucket"

  bucket_name            = var.s3_bucket_name
  enable_versioning      = true
  enable_encryption      = true
  enable_replication     = var.enable_s3_replication
  replication_region     = var.s3_replication_region
  environment            = var.environment

  tags = {
    Module = "s3"
  }
}

module "rds_postgres" {
  source = "./modules/rds_postgres"

  identifier           = "${var.project_name}-db-${var.environment}"
  instance_class       = var.rds_instance_class
  allocated_storage    = var.rds_allocated_storage
  db_name              = var.rds_db_name
  username             = var.rds_master_username
  password             = var.rds_master_password
  backup_retention     = var.rds_backup_retention_days
  multi_az             = var.rds_multi_az
  publicly_accessible  = false
  deletion_protection  = var.environment == "prod" ? true : false
  skip_final_snapshot  = var.environment == "dev" ? true : false
  environment          = var.environment

  tags = {
    Module = "rds"
  }
}

module "iam_role" {
  source = "./modules/iam_role"

  role_name              = var.iam_role_name
  environment            = var.environment
  s3_bucket_arn          = module.s3_bucket.bucket_arn
  rds_resource_id        = module.rds_postgres.db_resource_id

  # IRSA (OIDC-based) for prod
  oidc_provider_arn      = var.oidc_provider_arn
  oidc_aud               = var.oidc_aud
  namespace              = var.namespace
  service_account_name   = var.service_account_name

  tags = {
    Module = "iam"
  }
}
```

