## outputs.tf (Root)

```hcl
output "s3_bucket" {
  description = "S3 bucket details"
  value = {
    name   = module.s3_bucket.bucket_name
    arn    = module.s3_bucket.bucket_arn
    region = module.s3_bucket.region
  }
}

output "rds_instance" {
  description = "RDS instance details"
  value = {
    endpoint = module.rds_postgres.endpoint
    port     = module.rds_postgres.port
    database = module.rds_postgres.database_name
    username = var.rds_master_username
  }
  sensitive = false
}

