  value = {
    role_arn = module.iam_role.role_arn
    role_name = module.iam_role.role_name
  }
}

output "db_connection_string" {
  description = "Database connection string (for reference; store password securely)"
  value       = "postgresql://${var.rds_master_username}@${module.rds_postgres.endpoint}:${module.rds_postgres.port}/${var.rds_db_name}"
  sensitive   = true
}
