# Assume role policy: dev uses standard IAM user, prod uses IRSA (OIDC)
locals {
  assume_role_policy_dev = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
    }]
  })

  assume_role_policy_prod = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRoleWithWebIdentity"
      Effect = "Allow"
      Principal = {
        Federated = var.oidc_provider_arn
      }
      Condition = {
        StringEquals = {
          "${replace(var.oidc_provider_arn, "/^(.*provider/)/", "")}:aud" = var.oidc_aud
          "${replace(var.oidc_provider_arn, "/^(.*provider/)/", "")}:sub" = "system:serviceaccount:${var.namespace}:${var.service_account_name}"
        }
      }
    }]
  })
}

resource "aws_iam_role" "this" {
  name              = var.role_name
  assume_role_policy = var.environment == "prod" ? local.assume_role_policy_prod : local.assume_role_policy_dev

  tags = merge(
    var.tags,
    { Name = var.role_name }
  )
}

# Policy: S3 bucket access
resource "aws_iam_role_policy" "s3_access" {
  name   = "${var.role_name}-s3-policy"
  role   = aws_iam_role.this.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "s3:GetObject",
        "s3:PutObject",
        "s3:DeleteObject",
        "s3:ListBucket"
      ]
      Resource = [
        var.s3_bucket_arn,
        "${var.s3_bucket_arn}/*"
      ]
    }]
  })
}

# Policy: RDS access (connect to database)
resource "aws_iam_role_policy" "rds_access" {
  name   = "${var.role_name}-rds-policy"
  role   = aws_iam_role.this.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "rds-db:connect"
        ]
        Resource = "arn:aws:rds:*:*:db/${var.rds_resource_id}"
      },
      {
        Effect = "Allow"
        Action = [
          "rds:DescribeDBInstances"
        ]
        Resource = "*"
      }
    ]
  })
}

# Secrets Manager: read DB connection secret (optional)
resource "aws_iam_role_policy" "secrets_access" {
  count  = var.environment == "prod" ? 1 : 0
  name   = "${var.role_name}-secrets-policy"
  role   = aws_iam_role.this.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "secretsmanager:GetSecretValue"
      ]
      Resource = "arn:aws:secretsmanager:*:*:secret:${var.role_name}-*"
    }]
  })
}
